 static final int BG=Design.BG,INK=Design.INK,MUTED=Design.MUTED,WOOD=Design.WOOD,GREEN=Design.GREEN,SURFACE=Design.SURFACE;
 ExtraGames extra;FunGames fun;NASSync nas;
 final Handler handler=new Handler(Looper.getMainLooper());Content content;Store store;int child=-1;String screen="children",previousGame="math",message="";boolean active,animating,blocked;long lastTick;int frameIndex;Trace trace;BoardView board;TextView feedback,usageLabel;LinearLayout root;TextToSpeech speech;boolean speechReady;AlertDialog currentDialog;
 Profile profile(){return store.profiles[child];}
 final Runnable ticker=new Runnable(){public void run(){if(active&&!blocked&&child>=0){long now=SystemClock.elapsedRealtime(),elapsed=Math.max(0,now-lastTick);lastTick=now;Profile p=profile();boolean wasResting=p.restUntil>0;boolean ok=change(()->{p.consume(elapsed,System.currentTimeMillis());if(fun!=null)fun.charge(elapsed);});if(!ok)return;if(fun!=null)fun.afterTick();if(p.restUntil>0&&!screen.equals("rest")){stopPlayback();if(currentDialog!=null)currentDialog.dismiss();screen="rest";render("switch");}else if(wasResting&&p.restUntil==0){screen="home";render("math-card");}if(usageLabel!=null)usageLabel.setText(timeLabel());if(screen.equals("rest")&&feedback!=null)feedback.setText(restLabel());}handler.postDelayed(this,1000);}};
 final Runnable playback=new Runnable(){public void run(){if(!animating||!active||!screen.equals("route"))return;if(frameIndex<trace.frames().size()){board.frame=trace.frames().get(frameIndex++);board.invalidate();feedback.setText("走一遍 · "+Math.min(frameIndex-1,profile().commands.size())+" / "+profile().commands.size());handler.postDelayed(this,550);return;}animating=false;Profile p=profile();String result=trace.message();if(trace.success()){boolean first=!p.awards.containsKey(route().id);if(change(()->{p.routeSolved=true;p.award(route().id,"小鸭送信 · 第 "+(p.route+1)+" 关",3,System.currentTimeMillis());}))result+="  "+(first?"首次完成 +3 积分":"本关已获得积分");}message=result;render(trace.success()?"next":"run");}};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(5894);try{content=new Content(this);store=new Store(this,content);extra=new ExtraGames(this);fun=new FunGames(this);nas=new NASSync(this);}catch(Exception e){blocked=true;fatal("无法读取游戏或存档。原存档已保留，没有重置积分。\n请联系家长检查。",e);return;}speech=new TextToSpeech(this,status->{speechReady=status==TextToSpeech.SUCCESS;if(speechReady){int result=speech.setLanguage(Locale.SIMPLIFIED_CHINESE);speechReady=result>=0;}});render("child-0");}
 @Override protected void onResume(){super.onResume();active=true;lastTick=SystemClock.elapsedRealtime();handler.removeCallbacks(ticker);handler.postDelayed(ticker,1000);if(nas!=null)nas.resume();}
 @Override protected void onPause(){if(active&&child>=0&&!blocked){long elapsed=SystemClock.elapsedRealtime()-lastTick;Profile p=profile();change(()->{p.consume(Math.max(0,elapsed),System.currentTimeMillis());if(fun!=null)fun.charge(Math.max(0,elapsed));});}active=false;handler.removeCallbacks(ticker);stopPlayback();if(speech!=null)speech.stop();if(fun!=null)fun.pause();super.onPause();}
 @Override protected void onDestroy(){if(nas!=null)nas.close();handler.removeCallbacksAndMessages(null);if(speech!=null)speech.shutdown();if(fun!=null)fun.destroy();super.onDestroy();}
 boolean change(Runnable mutation){if(blocked)return false;String before;try{before=store.encode();}catch(Exception e){fatal("存档暂时不可用，已停止操作。",e);return false;}try{int awardsBefore=store.profiles[0].awards.size()+store.profiles[1].awards.size();mutation.run();store.save();if(nas!=null&&store.profiles[0].awards.size()+store.profiles[1].awards.size()>awardsBefore)nas.awardsChanged();return true;}catch(Exception e){try{store.restore(before);}catch(Exception ignored){}blocked=true;stopPlayback();fatal("保存失败，已撤回本次操作。积分没有扣除。\n原存档已保留，请检查电视储存空间。",e);return false;}}
