 TextView button(String title,String tag,Runnable action){TextView b=text(title,18,INK);b.setId(View.generateViewId());b.setTag(tag);b.setGravity(Gravity.CENTER);b.setPadding(dp(15),dp(8),dp(15),dp(8));b.setFocusable(true);b.setFocusableInTouchMode(true);b.setClickable(true);b.setBackground(background(SURFACE,0));b.setElevation(dp(2));b.setOnFocusChangeListener((v,focused)->{b.setBackground(background(focused?0xffE8DCB8:SURFACE,focused?WOOD:0));b.setElevation(dp(focused?5:2));});b.setOnClickListener(v->{if(!blocked)action.run();});return b;}
