 void header(){LinearLayout line=row();inRow(line,button(screen.equals("home")?"换人":"‹ 返回","back",this::back),0);TextView title=text("千臻乐园",25,INK);title.setTypeface(null,Typeface.BOLD);line.addView(title,new LinearLayout.LayoutParams(0,dp(46),1));usageLabel=text(timeLabel(),15,MUTED);inRow(line,usageLabel,0);inRow(line,button(CHILDREN[child]+" · "+profile().balance()+" 积分","points",()->{stopPlayback();screen="points";message="";render("redeem");}),0);add(root,line,-1,52);}
 String timeLabel(){if(child<0)return "";long remaining=profile().remaining(System.currentTimeMillis());return "剩余 "+String.format(Locale.ROOT,"%02d:%02d",remaining/60000,remaining/1000%60);}
