 void children(){gap(root,25);heading("今天，谁来玩？","选自己的名字，进度和积分各自保存");LinearLayout cards=row();String[] animals={"小熊","小兔"};for(int i=0;i<2;i++){final int n=i;TextView b=button(CHILDREN[i]+"\n\n"+store.profiles[i].balance()+" 积分","child-"+i,()->{child=n;screen="home";message="";lastTick=SystemClock.elapsedRealtime();render("math-card");});b.setTextSize(24);b.setCompoundDrawablesWithIntrinsicBounds(null,new AvatarDrawable(i==1,dp(94)),null,null);b.setCompoundDrawablePadding(dp(8));b.setContentDescription(CHILDREN[i]+"，"+animals[i]+"头像，"+store.profiles[i].balance()+"积分");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(220),1);p.setMargins(dp(10),dp(20),dp(10),dp(20));cards.addView(b,p);}weighted(root,cards);add(root,text("方向键选择 · 确定进入     每人使用 30 分钟，之后休息 2 小时",16,MUTED),-1,35);}
 int doneMath(){int n=0;for(Group g:content.groups)for(Question q:g.questions)if(profile().awards.containsKey(q.id))n++;return n;}
