 void openGame(boolean arithmetic){message="";previousGame=arithmetic?"math":"route";screen=(arithmetic?profile().arithmeticGroup:profile().routeGroup)<0?"groups-"+previousGame:previousGame;render(screen.startsWith("groups")?"group-0":arithmetic?"board":"forward");}
 void groups(boolean arithmetic){heading(arithmetic?"荷叶跳跳 · 选择题组":"小鸭送信 · 选择题组","原版题库 · 首次完成获得积分，复习不重复计分");LinearLayout list=column();for(int i=0;i<3;i++){final int g=i;String title=arithmetic?content.groups.get(i).title:ROUTE_GROUPS[i];TextView b=button(title+"  ·  "+(arithmetic?"8 题":"12 关"),"group-"+i,()->chooseGroup(arithmetic,g));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(72));p.setMargins(dp(5),dp(7),dp(5),dp(7));list.addView(b,p);}weighted(root,list);}
 void chooseGroup(boolean arithmetic,int group){Profile p=profile();if(!change(()->{if(arithmetic){if(p.arithmeticGroup!=group){p.arithmeticGroup=group;p.question=firstMath(group);p.arithmeticSolved=false;p.position=question().start;}}else if(p.routeGroup!=group){p.routeGroup=group;p.route=firstRoute(group);p.routeSolved=false;p.commands.clear();}}))return;screen=arithmetic?"math":"route";message="";render(arithmetic?"board":"forward");}
 int firstMath(int g){List<Question> qs=content.groups.get(g).questions;for(int i=0;i<qs.size();i++)if(!profile().awards.containsKey(qs.get(i).id))return i;return 0;}
 int firstRoute(int g){for(int i=g*12;i<g*12+12;i++)if(!profile().awards.containsKey(content.routes.get(i).id))return i;return g*12;}
