 void gameHeading(String title,String progress){LinearLayout line=row();TextView t=text(title,27,INK);t.setTypeface(null,Typeface.BOLD);line.addView(t,new LinearLayout.LayoutParams(0,dp(40),1));inRow(line,button("切换题组","group",()->{stopPlayback();if(screen.equals("extra")){extra.showGroups();return;}screen="groups-"+previousGame;render("group-0");}),0);inRow(line,button("朗读题目","speak",()->speak(progress)),0);add(root,line,-1,50);}
